import React, { useState, useEffect } from 'react';
import { LayoutGrid, Package, DollarSign, CreditCard, AlertTriangle, PlusCircle, CheckCircle, X } from 'lucide-react';

const initialInventory = [
  { id: 1, name: 'Heirloom Tomatoes', unit: 'lb', stock: 8, price: 5.50, lowStockThreshold: 10 },
  { id: 2, name: 'Rainbow Chard', unit: 'bunch', stock: 35, price: 4.00, lowStockThreshold: 15 },
  { id: 3, name: 'Organic Zucchini', unit: 'lb', stock: 52, price: 2.75, lowStockThreshold: 20 },
  { id: 4, name: 'Pasture-Raised Eggs', unit: 'dozen', stock: 24, price: 8.00, lowStockThreshold: 12 },
  { id: 5, name: 'Sourdough Boule', unit: 'loaf', stock: 15, price: 9.50, lowStockThreshold: 8 },
  { id: 6, name: 'Sweet Corn', unit: 'ear', stock: 120, price: 1.00, lowStockThreshold: 50 },
];

export default function MarketOSPrototype() {
  const [currentScreen, setCurrentScreen] = useState('dashboard');
  const [inventoryData, setInventoryData] = useState(initialInventory);
  const [notification, setNotification] = useState(null);

  const lowStockItems = inventoryData.filter(item => item.stock < item.lowStockThreshold);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  const NavItem = ({ icon, label, screenName }) => (
    <button
      onClick={() => setCurrentScreen(screenName)}
      className={`flex items-center w-full px-4 py-3 text-left rounded-lg transition-all duration-200 ${currentScreen === screenName ? 'bg-blue-100 text-blue-700 font-semibold' : 'text-slate-600 hover:bg-slate-100'}`}>
      {icon}
      <span className="ml-3">{label}</span>
    </button>
  );

  const DashboardScreen = () => (
    <div className="space-y-8">
      <div>
        <h1 className="text-2xl font-bold text-slate-800">Welcome back, Maria!</h1>
        <p className="text-sm text-slate-500">Here's your summary for Rodriguez Family Organics.</p>
      </div>
      {lowStockItems.length > 0 && (
        <div 
          className="p-4 bg-yellow-50 border-l-4 border-yellow-400 rounded-r-lg cursor-pointer hover:shadow-md transition-shadow"
          onClick={() => setCurrentScreen('inventory')}
        >
          <div className="flex items-center">
            <AlertTriangle className="h-6 w-6 text-yellow-500" />
            <div className="ml-3">
              <p className="text-md font-semibold text-yellow-800">Low Stock Alert</p>
              <p className="text-sm text-yellow-700">You have {lowStockItems.length} item(s) running low. Click to view.</p>
            </div>
          </div>
        </div>
      )}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="p-5 bg-white rounded-lg shadow-sm border border-slate-200">
          <h2 className="text-lg font-semibold text-slate-700">Today's Sales</h2>
          <p className="text-3xl font-bold text-slate-900 mt-2">$847.50</p>
          <p className="text-sm text-green-600 mt-1">+15% from last market day</p>
        </div>
        <div className="p-5 bg-white rounded-lg shadow-sm border border-slate-200">
          <h2 className="text-lg font-semibold text-slate-700">Transactions</h2>
          <p className="text-3xl font-bold text-slate-900 mt-2">68</p>
          <p className="text-sm text-slate-500 mt-1">Avg. $12.46 per transaction</p>
        </div>
        <div className="p-5 bg-white rounded-lg shadow-sm border border-slate-200">
          <h2 className="text-lg font-semibold text-slate-700">Top Seller</h2>
          <p className="text-3xl font-bold text-slate-900 mt-2">Heirloom Tomatoes</p>
          <p className="text-sm text-slate-500 mt-1">32 lbs sold today</p>
        </div>
      </div>
      <div>
        <h2 className="text-lg font-semibold text-slate-700 mb-3">Sales by Hour</h2>
        <div className="p-5 bg-white rounded-lg shadow-sm border border-slate-200 h-48 flex items-end space-x-4">
            {[_ => 30, _ => 50, _ => 90, _ => 75, _ => 40].map((h, i) => (
                <div key={i} className="flex-1 flex flex-col items-center justify-end">
                    <div style={{ height: `${h}%`}} className="w-3/4 bg-blue-500 rounded-t-md hover:bg-blue-600 transition-colors"></div>
                    <span className="text-xs text-slate-500 mt-2">{i+8}am</span>
                </div>
            ))}
        </div>
      </div>
    </div>
  );

  const InventoryScreen = () => {
    const [showForm, setShowForm] = useState(false);
    const [selectedItem, setSelectedItem] = useState(null);
    const [quantityToAdd, setQuantityToAdd] = useState('');

    const handleUpdateClick = (item) => {
        setSelectedItem(item);
        setShowForm(true);
    };

    const handleFormSubmit = (e) => {
        e.preventDefault();
        const amount = parseInt(quantityToAdd, 10);
        if (!isNaN(amount) && amount > 0) {
            setInventoryData(inventoryData.map(item => 
                item.id === selectedItem.id ? { ...item, stock: item.stock + amount } : item
            ));
            setNotification(`Added ${amount} ${selectedItem.unit}(s) of ${selectedItem.name}.`);
            setShowForm(false);
            setQuantityToAdd('');
            setSelectedItem(null);
        }
    };

    return (
      <div className="space-y-6 relative">
        <div className="flex justify-between items-center">
            <h1 className="text-2xl font-bold text-slate-800">Inventory</h1>
            <button className="flex items-center bg-blue-600 text-white px-4 py-2 rounded-lg font-semibold hover:bg-blue-700 transition-all duration-200 shadow-sm">
                <PlusCircle className="h-5 w-5 mr-2" />
                Add New Item
            </button>
        </div>

        {notification && (
            <div className="flex items-center p-4 bg-green-100 text-green-800 rounded-lg border border-green-200">
                <CheckCircle className="h-5 w-5 mr-3" />
                <p>{notification}</p>
            </div>
        )}

        <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="p-4 text-sm font-semibold text-slate-600">Product</th>
                <th className="p-4 text-sm font-semibold text-slate-600">In Stock</th>
                <th className="p-4 text-sm font-semibold text-slate-600">Price</th>
                <th className="p-4 text-sm font-semibold text-slate-600">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {inventoryData.map(item => (
                <tr key={item.id} className={`${item.stock < item.lowStockThreshold ? 'bg-yellow-50' : ''}`}>
                  <td className="p-4 font-medium text-slate-800">{item.name}</td>
                  <td className="p-4 text-slate-600">
                    <span className={`font-semibold ${item.stock < item.lowStockThreshold ? 'text-yellow-700' : 'text-slate-800'}`}>
                      {item.stock}
                    </span> {item.unit}s
                  </td>
                  <td className="p-4 text-slate-600">${item.price.toFixed(2)} / {item.unit}</td>
                  <td className="p-4">
                    <button 
                      onClick={() => handleUpdateClick(item)}
                      className="px-3 py-1 text-sm bg-slate-100 text-slate-700 rounded-md hover:bg-slate-200 transition-colors font-semibold">
                      Update Stock
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {showForm && selectedItem && (
            <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                <div className="bg-white rounded-lg shadow-2xl p-8 w-full max-w-md m-4">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-xl font-bold text-slate-800">Update Stock: {selectedItem.name}</h2>
                        <button onClick={() => setShowForm(false)} className="text-slate-500 hover:text-slate-800"><X/></button>
                    </div>
                    <p className="text-slate-600 mb-6">Current stock: <span className="font-bold">{selectedItem.stock} {selectedItem.unit}s</span>. How many new units are you adding?</p>
                    <form onSubmit={handleFormSubmit} className="space-y-4">
                        <div>
                            <label htmlFor="quantity" className="block text-sm font-medium text-slate-700">Quantity to Add</label>
                            <input
                                type="number"
                                id="quantity"
                                value={quantityToAdd}
                                onChange={(e) => setQuantityToAdd(e.target.value)}
                                className="mt-1 block w-full px-3 py-2 bg-white border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                                autoFocus
                                placeholder={`e.g., 50`}
                            />
                        </div>
                        <div className="flex justify-end pt-2 space-x-3">
                            <button type="button" onClick={() => setShowForm(false)} className="px-4 py-2 bg-slate-100 text-slate-800 rounded-lg hover:bg-slate-200 font-semibold">Cancel</button>
                            <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-semibold">Add to Stock</button>
                        </div>
                    </form>
                </div>
            </div>
        )}
      </div>
    );
  };

  const PlaceholderScreen = ({ title }) => (
      <div>
        <h1 className="text-2xl font-bold text-slate-800">{title}</h1>
        <p className="text-slate-500 mt-2">This feature is coming soon. This prototype focuses on the inventory management flow.</p>
        <div className="mt-6 p-12 bg-white border-2 border-dashed border-slate-300 rounded-lg flex items-center justify-center">
            <p className="text-slate-400 font-medium">{title} Content Area</p>
        </div>
      </div>
  );

  const renderScreen = () => {
    switch (currentScreen) {
      case 'dashboard': return <DashboardScreen />;
      case 'inventory': return <InventoryScreen />;
      case 'sales': return <PlaceholderScreen title="Sales & Reporting" />;
      case 'payments': return <PlaceholderScreen title="Digital Payments" />;
      default: return <DashboardScreen />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 flex" style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <aside className="w-64 bg-white border-r border-slate-200 p-6 flex flex-col">
        <div className="flex items-center space-x-2 mb-10">
            <svg className="h-8 w-8 text-blue-600" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
            <h1 className="text-xl font-bold text-slate-800">MarketOS</h1>
        </div>
        <nav className="space-y-2">
          <NavItem icon={<LayoutGrid size={20} />} label="Dashboard" screenName="dashboard" />
          <NavItem icon={<Package size={20} />} label="Inventory" screenName="inventory" />
          <NavItem icon={<DollarSign size={20} />} label="Sales" screenName="sales" />
          <NavItem icon={<CreditCard size={20} />} label="Payments" screenName="payments" />
        </nav>
      </aside>
      <main className="flex-1 p-8 md:p-12 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
            {renderScreen()}
        </div>
      </main>
    </div>
  );
}
